package com.example.dailytask.exception;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.authentication.BadCredentialsException;import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)public ResponseEntity<?> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}@ExceptionHandler(BadCredentialsException.class)public ResponseEntity<?> auth(BadCredentialsException e){return ResponseEntity.status(401).body(Map.of("message","Invalid username or password"));}@ExceptionHandler(Exception.class)public ResponseEntity<?> other(Exception e){return ResponseEntity.status(500).body(Map.of("message","Unexpected server error"));}}
